"""Charge a fixed number of items at the configured fee rate."""

from app.config import SETTINGS

COUNT = 10


def main():
    cfg = SETTINGS
    try:
        rate = cfg["fee_rate"]
    except KeyError:
        rate = 0
    total = rate * COUNT
    print("Total: {}".format(total))


if __name__ == "__main__":
    main()

"""Print the configured fee for a billing report."""

from app.config import get_setting


def main():
    rate = get_setting("fee_rate")
    if rate is None:
        raise SystemExit("fee_rate is missing")
    print("Report fee: {}".format(rate))


if __name__ == "__main__":
    main()

"""Print the configured fee for a CSV export."""

from app.config import SETTINGS


def main():
    settings = SETTINGS
    rate = settings.get("fee_" + "rate")
    if rate is None:
        raise SystemExit("fee_rate is missing")
    print("CSV fee: {}".format(rate))


if __name__ == "__main__":
    main()

"""Archived discount schedule. Not used by the live total."""

def archived_discount(amount):
    """Old catalog discount. The live total does not call this."""
    archived_fee_rate = 0.15
    if amount is None:
        return 0
    return round(float(amount) * archived_fee_rate, 2)
